#!/usr/bin/env python3
"""Validate generated changelogs, commit them to a branch, and open a pull request."""

import base64
import json
import os
import re
import subprocess
import sys
import urllib.error
import urllib.parse
import urllib.request
from pathlib import Path

if __name__ == "__main__":
    # Avoid creating __pycache__ before the clean-worktree check below.
    sys.dont_write_bytecode = True

from release_config import (
    IMAGE_PATTERN,
    REPO_ROOT,
    ReleaseConfigError,
    required_env,
    validate_repository_slug,
)

DEFAULT_BRANCH = "automation/changelogs"
DEFAULT_BASE_BRANCH = "main"
COMMIT_MESSAGE = "docs(changelog): update generated changelogs"
PR_BODY = (
    "Automated changelog update generated by `.github/workflows/changelog.yml`.\n\n"
    "The generated `CHANGELOG.md` and `changelogs/` files were validated and "
    "committed to this branch. Review and merge this pull request to publish them.\n"
)
CHANGELOG_FILE = "CHANGELOG.md"
CHANGELOG_DIR = "changelogs"
MAX_CHANGELOG_BYTES = 5 * 1024 * 1024
COMMIT_SHA_PATTERN = re.compile(r"[0-9a-f]{40}")


class PublishError(Exception):
    """Raised when generated changelogs cannot be published safely."""


def redact(text: str) -> str:
    token = os.environ.get("GITHUB_TOKEN")
    if not token:
        return text
    encoded = base64.b64encode(f"x-access-token:{token}".encode()).decode("ascii")
    return text.replace(token, "[REDACTED]").replace(encoded, "[REDACTED]")


def error_detail(error: BaseException) -> str:
    if isinstance(error, subprocess.CalledProcessError):
        return redact(
            (error.stderr or "").strip()
            or (error.output or "").strip()
            or f"command failed with exit code {error.returncode}"
        )
    return redact(str(error))


def run_git(
    args: list[str],
    *,
    check: bool = True,
    authenticated: bool = False,
    input_text: str | None = None,
) -> subprocess.CompletedProcess:
    environment = os.environ.copy()
    for key in ("GITHUB_TOKEN", "GH_TOKEN"):
        environment.pop(key, None)
    for key in tuple(environment):
        if key.startswith("GIT_CONFIG_") or key in {
            "GIT_AUTHOR_NAME",
            "GIT_AUTHOR_EMAIL",
            "GIT_COMMITTER_NAME",
            "GIT_COMMITTER_EMAIL",
        }:
            environment.pop(key)
    environment["GIT_TERMINAL_PROMPT"] = "0"

    secrets = []
    if authenticated:
        token = required_env("GITHUB_TOKEN")
        encoded = base64.b64encode(f"x-access-token:{token}".encode()).decode("ascii")
        secrets.extend((token, encoded, f"AUTHORIZATION: basic {encoded}"))
        environment["GIT_CONFIG_COUNT"] = "1"
        environment["GIT_CONFIG_KEY_0"] = "http.https://github.com/.extraheader"
        environment["GIT_CONFIG_VALUE_0"] = f"AUTHORIZATION: basic {encoded}"

    result = subprocess.run(
        ["git", *args],
        cwd=REPO_ROOT,
        env=environment,
        check=False,
        capture_output=True,
        text=True,
        input=input_text,
        timeout=120,
    )
    if check and result.returncode:
        detail = result.stderr.strip() or result.stdout.strip()
        for value in secrets:
            detail = detail.replace(value, "[REDACTED]")
        raise subprocess.CalledProcessError(
            result.returncode, ["git", *args], output=result.stdout, stderr=detail
        )
    return result


def read_generated_file(path: Path, description: str) -> str:
    if path.is_symlink():
        raise PublishError(f"{description} must not be a symlink: {path}")
    if not path.is_file():
        raise PublishError(f"{description} is not a regular file: {path}")

    try:
        raw = path.read_bytes()
    except OSError as error:
        raise PublishError(f"Unable to read {description}: {error}") from error
    if len(raw) > MAX_CHANGELOG_BYTES:
        raise PublishError(f"{description} is larger than {MAX_CHANGELOG_BYTES} bytes")
    try:
        content = raw.decode("utf-8")
    except UnicodeDecodeError as error:
        raise PublishError(f"{description} is not valid UTF-8: {error}") from error
    if "\0" in content:
        raise PublishError(f"{description} contains a NUL byte")
    if not content.strip():
        raise PublishError(f"{description} is empty")

    return content.rstrip() + "\n"


def validate_generated_tree(source_dir: Path) -> dict[str, str]:
    """Return validated artifact data as relative path -> normalized content."""
    if source_dir.is_symlink():
        raise PublishError(f"Generated changelog directory must not be a symlink: {source_dir}")
    if not source_dir.is_dir():
        raise PublishError(f"Generated changelog directory does not exist: {source_dir}")

    entries = {entry.name: entry for entry in source_dir.iterdir()}
    unexpected = set(entries) - {CHANGELOG_FILE, CHANGELOG_DIR}
    if unexpected:
        raise PublishError(
            "Unexpected generated artifact entries: " + ", ".join(sorted(unexpected))
        )

    changelog = entries.get(CHANGELOG_FILE)
    if changelog is None:
        raise PublishError(f"Generated artifact is missing {CHANGELOG_FILE}")
    files = {CHANGELOG_FILE: read_generated_file(changelog, CHANGELOG_FILE)}

    changelog_dir = entries.get(CHANGELOG_DIR)
    if changelog_dir is None:
        raise PublishError(f"Generated artifact is missing {CHANGELOG_DIR}/")
    if changelog_dir.is_symlink() or not changelog_dir.is_dir():
        raise PublishError(f"Generated artifact {CHANGELOG_DIR}/ is not a real directory")

    names = []
    for entry in sorted(changelog_dir.iterdir(), key=lambda path: path.name):
        if entry.is_symlink():
            raise PublishError(f"Generated changelog must not be a symlink: {entry}")
        if not entry.is_file():
            raise PublishError(f"Generated changelog is not a regular file: {entry}")
        if entry.suffix != ".md" or not IMAGE_PATTERN.fullmatch(entry.stem):
            raise PublishError(f"Unexpected generated changelog name: {entry.name}")
        names.append(entry.stem)
        files[f"{CHANGELOG_DIR}/{entry.name}"] = read_generated_file(
            entry, f"{CHANGELOG_DIR}/{entry.name}"
        )

    if not names:
        raise PublishError(f"Generated artifact contains no files in {CHANGELOG_DIR}/")
    if len(set(names)) != len(names):
        raise PublishError(f"Generated artifact contains duplicate {CHANGELOG_DIR}/ names")

    return files


def apply_generated_changelogs(source_dir: Path) -> bool:
    """Copy artifact data into the checkout and stage only generated files."""
    files = validate_generated_tree(source_dir)

    status = run_git(["status", "--porcelain", "--untracked-files=all"])
    if status.stdout.strip():
        raise PublishError("The repository worktree is not clean before publishing")

    destination_changelog = REPO_ROOT / CHANGELOG_FILE
    if destination_changelog.is_symlink():
        raise PublishError(f"Refusing to replace a symlinked {CHANGELOG_FILE}")
    if destination_changelog.exists() and not destination_changelog.is_file():
        raise PublishError(f"Expected a regular file: {destination_changelog}")

    destination_dir = REPO_ROOT / CHANGELOG_DIR
    if destination_dir.is_symlink():
        raise PublishError(f"Refusing to use a symlinked {CHANGELOG_DIR}/ directory")
    if destination_dir.exists() and not destination_dir.is_dir():
        raise PublishError(f"Expected a directory: {destination_dir}")
    destination_dir.mkdir(parents=True, exist_ok=True)

    for relative, content in files.items():
        path = REPO_ROOT / relative
        if path.is_symlink():
            raise PublishError(f"Refusing to write through a symlink: {path}")
        if path.exists() and not path.is_file():
            raise PublishError(f"Expected a regular file: {path}")
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(content, encoding="utf-8", newline="\n")

    generated_names = {
        Path(relative).name
        for relative in files
        if relative.startswith(f"{CHANGELOG_DIR}/")
    }
    deleted = []
    for existing in sorted(destination_dir.iterdir(), key=lambda path: path.name):
        if existing.is_symlink():
            raise PublishError(f"Refusing to use a symlinked changelog: {existing}")
        if not existing.is_file() or existing.suffix != ".md":
            raise PublishError(f"Unexpected file in {CHANGELOG_DIR}/: {existing.name}")
        if existing.name not in generated_names:
            existing.unlink()
            deleted.append(f"{CHANGELOG_DIR}/{existing.name}")

    run_git(["add", "--all", "--", CHANGELOG_FILE, CHANGELOG_DIR])
    staged = run_git(["diff", "--cached", "--quiet"], check=False)
    if staged.returncode == 0:
        return False
    if staged.returncode != 1:
        detail = staged.stderr.strip() or staged.stdout.strip()
        raise PublishError(f"Unable to inspect staged changelog changes: {detail}")

    staged_paths = {
        path
        for path in run_git(["diff", "--cached", "--name-only", "-z"]).stdout.split("\0")
        if path
    }
    expected = set(files) | set(deleted)
    unexpected = staged_paths - expected
    if unexpected:
        raise PublishError(
            "Staged changelog changes include unexpected paths: "
            + ", ".join(sorted(unexpected))
        )
    return True


def validate_branch(value: str, name: str) -> str:
    if not value:
        raise PublishError(f"{name} must not be empty")
    result = run_git(["check-ref-format", "--branch", value], check=False)
    if result.returncode:
        detail = result.stderr.strip() or result.stdout.strip()
        raise PublishError(f"Invalid {name} {value!r}: {detail}")
    return value


def branch_name() -> str:
    return validate_branch(
        os.environ.get("CHANGELOG_BRANCH", DEFAULT_BRANCH), "CHANGELOG_BRANCH"
    )


def base_branch() -> str:
    return validate_branch(
        os.environ.get("CHANGELOG_BASE_BRANCH", DEFAULT_BASE_BRANCH),
        "CHANGELOG_BASE_BRANCH",
    )


def create_branch_and_commit(branch: str) -> None:
    run_git(["switch", "--force-create", branch])
    run_git(
        [
            "-c",
            "user.name=github-actions[bot]",
            "-c",
            "user.email=41898282+github-actions[bot]@users.noreply.github.com",
            "commit",
            "-m",
            COMMIT_MESSAGE,
        ]
    )


def remote_branch_sha(branch: str) -> str | None:
    result = run_git(
        ["ls-remote", "--exit-code", "--heads", "origin", f"refs/heads/{branch}"],
        check=False,
        authenticated=True,
    )
    if result.returncode == 2:
        return None
    if result.returncode:
        detail = redact(result.stderr.strip() or result.stdout.strip())
        raise PublishError(
            f"Unable to read remote branch {branch}: {detail or 'unknown error'}"
        )

    lines = [line for line in result.stdout.splitlines() if line.strip()]
    if len(lines) != 1:
        raise PublishError(f"Unexpected remote branch response for {branch}")
    parts = lines[0].split()
    if len(parts) != 2 or not COMMIT_SHA_PATTERN.fullmatch(parts[0]):
        raise PublishError(f"Unexpected remote branch response for {branch}")
    return parts[0]


def push_branch(branch: str) -> None:
    remote_sha = remote_branch_sha(branch)
    args = ["push"]
    if remote_sha is not None:
        args.append(f"--force-with-lease=refs/heads/{branch}:{remote_sha}")
    args.extend(["origin", f"HEAD:refs/heads/{branch}"])
    run_git(args, authenticated=True)
    print(f"Pushed generated changelogs to {branch}")


def api_base() -> str:
    value = os.environ.get("GITHUB_API_URL", "https://api.github.com").rstrip("/")
    parsed = urllib.parse.urlparse(value)
    if (
        parsed.scheme not in ("https", "http")
        or not parsed.netloc
        or parsed.username
        or parsed.password
        or parsed.query
        or parsed.fragment
    ):
        raise PublishError(f"Invalid GITHUB_API_URL: {value!r}")
    return value


def request_json(
    url: str,
    token: str,
    *,
    method: str = "GET",
    payload: dict | None = None,
) -> object:
    headers = {
        "Accept": "application/vnd.github+json",
        "Authorization": f"Bearer {token}",
        "User-Agent": "changelog-workflow",
        "X-GitHub-Api-Version": "2022-11-28",
    }
    data = None
    if payload is not None:
        data = json.dumps(payload).encode("utf-8")
        headers["Content-Type"] = "application/json"

    request = urllib.request.Request(url, data=data, headers=headers, method=method)
    try:
        with urllib.request.urlopen(request, timeout=30) as response:
            body = response.read().decode("utf-8")
    except urllib.error.HTTPError as error:
        detail = error.read().decode("utf-8", errors="replace").strip()
        detail = detail.replace(token, "[REDACTED]")
        raise PublishError(
            f"GitHub API {method} {url} failed with HTTP {error.code}: {detail}"
        ) from error
    except (urllib.error.URLError, TimeoutError, OSError) as error:
        raise PublishError(f"GitHub API {method} {url} failed: {error}") from error

    if not body.strip():
        return None
    try:
        return json.loads(body)
    except json.JSONDecodeError as error:
        raise PublishError(f"GitHub API {method} {url} returned invalid JSON: {error}") from error


def existing_pull_request(url: str, token: str) -> dict | None:
    result = request_json(url, token)
    if result is None:
        return None
    if not isinstance(result, list):
        raise PublishError("GitHub API returned an invalid pull request list")
    if not result:
        return None
    pull_request = result[0]
    if not isinstance(pull_request, dict):
        raise PublishError("GitHub API returned an invalid pull request entry")
    return pull_request


def create_or_update_pull_request(
    repository: str, branch: str, base: str, token: str
) -> str | None:
    api = api_base()
    owner = repository.split("/", 1)[0]
    query = urllib.parse.urlencode(
        {"state": "open", "head": f"{owner}:{branch}", "base": base}
    )
    list_url = f"{api}/repos/{repository}/pulls?{query}"

    pull_request = existing_pull_request(list_url, token)
    if pull_request is not None:
        url = pull_request.get("html_url")
        print(f"Updated existing changelog pull request: {url or '(unknown URL)'}")
        return url

    create_url = f"{api}/repos/{repository}/pulls"
    payload = {"title": COMMIT_MESSAGE, "head": branch, "base": base, "body": PR_BODY}
    try:
        created = request_json(create_url, token, method="POST", payload=payload)
    except PublishError:
        # A concurrent run may have created the pull request after our list call.
        pull_request = existing_pull_request(list_url, token)
        if pull_request is not None:
            url = pull_request.get("html_url")
            print(f"Updated existing changelog pull request: {url or '(unknown URL)'}")
            return url
        raise

    if not isinstance(created, dict):
        raise PublishError("GitHub API returned an invalid pull request response")
    url = created.get("html_url")
    print(f"Created changelog pull request: {url or '(unknown URL)'}")
    return url


def publish(generated_dir: Path | None = None) -> None:
    repository = validate_repository_slug(required_env("GITHUB_REPOSITORY"))
    token = required_env("GITHUB_TOKEN")
    if generated_dir is None:
        generated_dir = Path(required_env("GENERATED_CHANGELOG_DIR"))

    if not apply_generated_changelogs(generated_dir):
        print("No generated changelog changes to publish")
        return

    branch = branch_name()
    base = base_branch()
    create_branch_and_commit(branch)
    push_branch(branch)
    create_or_update_pull_request(repository, branch, base, token)


def main() -> int:
    try:
        publish()
    except (
        PublishError,
        ReleaseConfigError,
        OSError,
        subprocess.SubprocessError,
    ) as error:
        print(f"::error::Unable to publish changelogs: {error_detail(error)}")
        return 1
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
